package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCommandExitCodes(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantCode int
	}{
		{"init success", []string{"init"}, 0},
		{"get missing key", []string{"get", "nonexistent"}, 1},
		{"set success", []string{"set", "key", "value"}, 0},
		{"delete missing", []string{"delete", "missing"}, 1},
		{"validate valid config", []string{"validate"}, 0},
		{"list empty", []string{"list"}, 0},
		{"unknown command", []string{"unknown"}, 2},
		{"missing required arg", []string{"set", "key"}, 2},
		{"no command", []string{}, 2},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			code := run(tt.args)
			if code != tt.wantCode {
				t.Errorf("got exit code %d, want %d", code, tt.wantCode)
			}
		})
	}
}

func TestFlagParsing(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantConfig string
		wantFormat string
		wantQuiet  bool
	}{
		{"default flags", []string{"list"}, "~/.config/app/config.yaml", "text", false},
		{"custom config", []string{"--config", "/tmp/c.yaml", "list"}, "/tmp/c.yaml", "text", false},
		{"json format", []string{"--format", "json", "list"}, "~/.config/app/config.yaml", "json", false},
		{"quiet mode", []string{"--quiet", "set", "k", "v"}, "~/.config/app/config.yaml", "text", true},
		{"combined flags", []string{"--config", "/x", "--format", "yaml", "--quiet", "get", "k"}, "/x", "yaml", true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			opts := parseFlags(tt.args)
			if opts.ConfigPath != tt.wantConfig {
				t.Errorf("config = %q, want %q", opts.ConfigPath, tt.wantConfig)
			}
			if opts.Format != tt.wantFormat {
				t.Errorf("format = %q, want %q", opts.Format, tt.wantFormat)
			}
			if opts.Quiet != tt.wantQuiet {
				t.Errorf("quiet = %v, want %v", opts.Quiet, tt.wantQuiet)
			}
		})
	}
}

func TestOutputStreams(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantStdout string
		wantStderr string
	}{
		{"list outputs to stdout", []string{"list"}, "key1=value1\n", ""},
		{"error to stderr", []string{"get", "missing"}, "", "error: key not found\n"},
		{"quiet suppresses stdout", []string{"--quiet", "set", "k", "v"}, "", ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			runWithIO(tt.args, nil, stdout, stderr)
			if stdout.String() != tt.wantStdout {
				t.Errorf("stdout = %q, want %q", stdout.String(), tt.wantStdout)
			}
			if stderr.String() != tt.wantStderr {
				t.Errorf("stderr = %q, want %q", stderr.String(), tt.wantStderr)
			}
		})
	}
}

func TestFileOperations(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")

	tests := []struct {
		name    string
		args    []string
		setup   func()
		check   func(t *testing.T)
	}{
		{
			name: "init creates file",
			args: []string{"--config", configPath, "init"},
			check: func(t *testing.T) {
				if _, err := os.Stat(configPath); os.IsNotExist(err) {
					t.Error("config file not created")
				}
			},
		},
		{
			name:  "set persists value",
			args:  []string{"--config", configPath, "set", "mykey", "myvalue"},
			setup: func() { os.WriteFile(configPath, []byte("{}"), 0644) },
			check: func(t *testing.T) {
				data, _ := os.ReadFile(configPath)
				if !bytes.Contains(data, []byte("mykey")) {
					t.Error("key not persisted")
				}
			},
		},
		{
			name:  "delete removes key",
			args:  []string{"--config", configPath, "delete", "mykey"},
			setup: func() { os.WriteFile(configPath, []byte("mykey: myvalue"), 0644) },
			check: func(t *testing.T) {
				data, _ := os.ReadFile(configPath)
				if bytes.Contains(data, []byte("mykey")) {
					t.Error("key not deleted")
				}
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			os.Remove(configPath)
			if tt.setup != nil {
				tt.setup()
			}
			run(tt.args)
			tt.check(t)
		})
	}
}
